gaI9(){return"No symbol has been bought again after a full exit."},
gaIa(){return"Too few second rounds to read."},
aIb(a,b,c){var s=null,r=this.a,q=A.aw(b,s,r,s,"symbol","symbols",s,s),p=""+a,o=A.aw(a,s,r,s,p+" round",p+" rounds",s,s)
return A.v(c)+" "+q+" bought again after a full exit, "+o+" so far."},
